// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier.oracle;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;

/**
 * Exhaustively compares the finite-bag oracle with independent, direct SPARQL bag-algebra specifications.
 *
 * <p>
 * The single-bag universe contains all {@code 3^2} partial bindings of {@code x} and {@code y} over the two-term domain
 * {@code {0, 1}}. The binary-operator universe is the seven-binding subset that retains the empty binding, every
 * one-variable binding, compatible two-variable bindings, and incompatible values while keeping the ordered bag-pair
 * cross product suitable for routine CI.
 */
class FrontierFiniteBagExhaustiveTest {

	private static final BigInteger ONE = BigInteger.ONE;
	private static final OracleFrontierLayout X = OracleFrontierLayout.of("x");
	private static final OracleFrontierLayout XY = OracleFrontierLayout.of("x", "y");

	@Test
	void exhaustivelyChecksFiniteBagAndFrontierSemantics() {
		List<SpecBinding> completeUniverse = allPartialBindings();
		List<SpecBag> completeBags = allBinaryBags(completeUniverse);
		long assertionCount = 0L;

		for (SpecBag specification : completeBags) {
			OracleBag bag = specification.toOracleBag();
			OracleFrontierMeasure frontier = OracleFrontierMeasure.fromBag(bag, XY);

			assertEquals(ExactRational.of(specification.cardinality()), frontier.mass());
			assertionCount++;

			ExactRational stratumMass = frontier.byMask()
					.values()
					.stream()
					.map(OracleWeightedMeasure::mass)
					.reduce(ExactRational.ZERO, ExactRational::add);
			assertEquals(frontier.mass(), stratumMass);
			assertionCount++;

			assertEquals(bag.project(X), bag.project(XY).project(X));
			assertionCount++;

			assertEquals(bag.distinct(), bag.distinct().distinct());
			assertionCount++;

			assertEquals(bag.cardinality(), bag.project(X).cardinality());
			assertionCount++;
		}

		List<SpecBinding> pairUniverse = List.of(
				SpecBinding.empty(),
				SpecBinding.x(0L),
				SpecBinding.x(1L),
				SpecBinding.y(0L),
				SpecBinding.y(1L),
				SpecBinding.xy(0L, 0L),
				SpecBinding.xy(1L, 1L));
		List<SpecBag> pairBags = allBinaryBags(pairUniverse);

		for (SpecBag leftSpecification : pairBags) {
			OracleBag left = leftSpecification.toOracleBag();
			OracleFrontierMeasure leftFrontier = OracleFrontierMeasure.fromBag(left, XY);
			for (SpecBag rightSpecification : pairBags) {
				OracleBag right = rightSpecification.toOracleBag();
				OracleFrontierMeasure rightFrontier = OracleFrontierMeasure.fromBag(right, XY);

				SpecBag expectedJoinSpecification = directJoin(leftSpecification, rightSpecification);
				OracleBag expectedJoin = expectedJoinSpecification.toOracleBag();
				assertEquals(expectedJoin, left.naturalJoin(right));
				assertionCount++;

				assertEquals(
						OracleFrontierMeasure.fromBag(expectedJoin, XY),
						leftFrontier.naturalJoin(rightFrontier, XY));
				assertionCount++;

				assertEquals(directMinus(leftSpecification, rightSpecification).toOracleBag(), left.minus(right));
				assertionCount++;

				OracleBag exists = left.exists(right);
				OracleBag notExists = left.notExists(right);
				assertEquals(left, exists.union(notExists));
				assertionCount++;

				assertTrue(Collections.disjoint(exists.entries().keySet(), notExists.entries().keySet()));
				assertionCount++;

				assertEquals(expectedJoin.union(notExists), left.optional(right));
				assertionCount++;

				assertEquals(
						left.cardinality().add(right.cardinality()),
						left.union(right).cardinality());
				assertionCount++;

				// This direct specification is deliberately independent of NOT EXISTS. It closes the reference
				// package's historical gap where eight pair assertions were reported but only seven were executed.
				assertEquals(directExists(leftSpecification, rightSpecification).toOracleBag(), exists);
				assertionCount++;
			}
		}

		assertEquals(133_632L, assertionCount);
	}

	private static List<SpecBinding> allPartialBindings() {
		List<SpecBinding> bindings = new ArrayList<>(9);
		for (int xState = -1; xState <= 1; xState++) {
			for (int yState = -1; yState <= 1; yState++) {
				Long x = xState < 0 ? null : (long) xState;
				Long y = yState < 0 ? null : (long) yState;
				bindings.add(new SpecBinding(x, y));
			}
		}
		return List.copyOf(bindings);
	}

	private static List<SpecBag> allBinaryBags(List<SpecBinding> universe) {
		int bagCount = 1 << universe.size();
		List<SpecBag> bags = new ArrayList<>(bagCount);
		for (int mask = 0; mask < bagCount; mask++) {
			Map<SpecBinding, BigInteger> entries = new LinkedHashMap<>();
			for (int bindingIndex = 0; bindingIndex < universe.size(); bindingIndex++) {
				if ((mask & (1 << bindingIndex)) != 0) {
					entries.put(universe.get(bindingIndex), ONE);
				}
			}
			bags.add(new SpecBag(entries));
		}
		return List.copyOf(bags);
	}

	private static SpecBag directJoin(SpecBag left, SpecBag right) {
		Map<SpecBinding, BigInteger> result = new LinkedHashMap<>();
		for (Map.Entry<SpecBinding, BigInteger> leftEntry : left.entries().entrySet()) {
			for (Map.Entry<SpecBinding, BigInteger> rightEntry : right.entries().entrySet()) {
				if (leftEntry.getKey().compatibleWith(rightEntry.getKey())) {
					add(
							result,
							leftEntry.getKey().merge(rightEntry.getKey()),
							leftEntry.getValue().multiply(rightEntry.getValue()));
				}
			}
		}
		return new SpecBag(result);
	}

	private static SpecBag directExists(SpecBag left, SpecBag right) {
		Map<SpecBinding, BigInteger> result = new LinkedHashMap<>();
		for (Map.Entry<SpecBinding, BigInteger> leftEntry : left.entries().entrySet()) {
			if (hasCompatibleRight(leftEntry.getKey(), right)) {
				result.put(leftEntry.getKey(), leftEntry.getValue());
			}
		}
		return new SpecBag(result);
	}

	private static SpecBag directMinus(SpecBag left, SpecBag right) {
		Map<SpecBinding, BigInteger> result = new LinkedHashMap<>();
		for (Map.Entry<SpecBinding, BigInteger> leftEntry : left.entries().entrySet()) {
			boolean remove = false;
			for (Map.Entry<SpecBinding, BigInteger> rightEntry : right.entries().entrySet()) {
				if (rightEntry.getValue().signum() > 0
						&& leftEntry.getKey().compatibleWith(rightEntry.getKey())
						&& leftEntry.getKey().hasNonEmptyDomainOverlap(rightEntry.getKey())) {
					remove = true;
					break;
				}
			}
			if (!remove) {
				result.put(leftEntry.getKey(), leftEntry.getValue());
			}
		}
		return new SpecBag(result);
	}

	private static boolean hasCompatibleRight(SpecBinding left, SpecBag right) {
		for (Map.Entry<SpecBinding, BigInteger> rightEntry : right.entries().entrySet()) {
			if (rightEntry.getValue().signum() > 0 && left.compatibleWith(rightEntry.getKey())) {
				return true;
			}
		}
		return false;
	}

	private static void add(Map<SpecBinding, BigInteger> bag, SpecBinding binding, BigInteger multiplicity) {
		bag.merge(binding, multiplicity, BigInteger::add);
	}

	private record SpecBag(Map<SpecBinding, BigInteger> entries) {

		private SpecBag {
			entries = Map.copyOf(entries);
		}

		private BigInteger cardinality() {
			BigInteger cardinality = BigInteger.ZERO;
			for (BigInteger multiplicity : entries.values()) {
				cardinality = cardinality.add(multiplicity);
			}
			return cardinality;
		}

		private OracleBag toOracleBag() {
			OracleBag result = OracleBag.empty();
			for (Map.Entry<SpecBinding, BigInteger> entry : entries.entrySet()) {
				result = result.plus(entry.getKey().toOracleBinding(), entry.getValue());
			}
			return result;
		}
	}

	private record SpecBinding(Long x, Long y) {

		private static SpecBinding empty() {
			return new SpecBinding(null, null);
		}

		private static SpecBinding x(long value) {
			return new SpecBinding(value, null);
		}

		private static SpecBinding y(long value) {
			return new SpecBinding(null, value);
		}

		private static SpecBinding xy(long x, long y) {
			return new SpecBinding(x, y);
		}

		private boolean compatibleWith(SpecBinding other) {
			return (x == null || other.x == null || x.equals(other.x))
					&& (y == null || other.y == null || y.equals(other.y));
		}

		private boolean hasNonEmptyDomainOverlap(SpecBinding other) {
			return x != null && other.x != null || y != null && other.y != null;
		}

		private SpecBinding merge(SpecBinding other) {
			if (!compatibleWith(other)) {
				throw new IllegalArgumentException("Cannot merge incompatible bindings");
			}
			return new SpecBinding(x == null ? other.x : x, y == null ? other.y : y);
		}

		private OracleBinding toOracleBinding() {
			Map<String, Long> values = new LinkedHashMap<>(2);
			if (x != null) {
				values.put("x", x);
			}
			if (y != null) {
				values.put("y", y);
			}
			return OracleBinding.of(values);
		}
	}
}
